use bevy::prelude::*;
use crate::{docking::{DockViewer,TransformEdit},history::{TransformHistory,TransformSnapshot},project::ProjectState,scene_model::EditorParent,selection::SelectionState,viewport::EditorEntity};
#[derive(Clone,Default)]pub struct UiActions{pub create_entity:bool,pub delete_entity:Option<Entity>,pub duplicate_entity:Option<Entity>,pub save_requested:bool,pub transform_edit:Option<TransformEdit>,pub name_edit:Option<String>,pub visibility_edit:Option<bool>,pub parent_selected:bool,pub unparent_selected:bool}
impl UiActions{pub fn from(v:&DockViewer<'_>)->Self{Self{create_entity:v.create_entity,delete_entity:v.delete_entity,duplicate_entity:v.duplicate_entity,save_requested:v.save_requested,transform_edit:v.transform_edit,name_edit:v.name_edit.clone(),visibility_edit:v.visibility_edit,parent_selected:v.parent_selected,unparent_selected:v.unparent_selected}}}
pub fn select_clicked_entity(event:On<Pointer<Click>>,mut selection:ResMut<SelectionState>){selection.select(event.entity)}
pub fn apply_entity_actions(a:&UiActions,commands:&mut Commands,selection:&mut SelectionState,project:&mut ProjectState,history:&mut TransformHistory,transforms:&Query<&Transform,With<EditorEntity>>,parents:&mut Query<&mut EditorParent,With<EditorEntity>>){if a.create_entity{let e=commands.spawn((Transform::default(),Name::new("Entity"),Visibility::Inherited,Pickable::default(),EditorEntity,EditorParent(None))).id();commands.entity(e).observe(select_clicked_entity);selection.select(e);project.dirty=true}if let Some(e)=a.duplicate_entity&&let Ok(t)=transforms.get(e){let n=commands.spawn((*t,Name::new("Duplicate"),Visibility::Inherited,Pickable::default(),EditorEntity,EditorParent(None))).id();commands.entity(n).observe(select_clicked_entity);selection.select(n);project.dirty=true}if let Some(e)=a.delete_entity&&selection.contains(e){commands.entity(e).despawn();selection.entities.retain(|x|*x!=e);selection.focused=selection.entities.last().copied();project.dirty=true}if a.parent_selected&&selection.entities.len()>=2{if let Some(parent)=selection.primary(){for e in selection.entities.clone(){if e!=parent{if let Ok(mut p)=parents.get_mut(e){p.0=Some(parent)}}}project.dirty=true}}if a.unparent_selected{for e in selection.entities.clone(){if let Ok(mut p)=parents.get_mut(e){p.0=None}}project.dirty=true}if let Some(name)=&a.name_edit{if let Some(e)=selection.primary(){commands.entity(e).insert(Name::new(name.clone()));project.dirty=true}}if let Some(v)=a.visibility_edit{if let Some(e)=selection.primary(){commands.entity(e).insert(if v{Visibility::Visible}else{Visibility::Hidden});project.dirty=true}}if let Some(edit)=a.transform_edit{if let Ok(current)=transforms.get(edit.entity){let next=Transform{translation:edit.translation,rotation:Quat::from_euler(EulerRot::XYZ,edit.rotation.x.to_radians(),edit.rotation.y.to_radians(),edit.rotation.z.to_radians()),scale:edit.scale};if *current!=next{history.push(TransformSnapshot{entity:edit.entity,transform:*current});commands.entity(edit.entity).insert(next);project.dirty=true}}}}
